#!/usr/bin/env node

/*
 * Isolated browser contract for the WhatsApp UI. Run this file in the
 * playwright-mcp container after copying the app's public directory to it.
 * Every API request is fulfilled by the route below; no connector is touched.
 */
import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { promises as fs } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const playwrightModule = process.env.PLAYWRIGHT_MODULE || '/app/node_modules/playwright/index.mjs';
const { chromium } = await import(playwrightModule);

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const sourceDir = path.resolve(process.env.UI_SOURCE_DIR || path.join(scriptDir, '..', 'public'));
const outputDir = path.resolve(process.env.UI_OUTPUT_DIR || '/data/output/socialmedia-whatsapp-ui');
const executablePath = process.env.PLAYWRIGHT_EXECUTABLE_PATH || '/ms-playwright/chromium-1246/chrome-linux64/chrome';

function createToneWav(durationSeconds = 1.2, sampleRate = 8000) {
  const sampleCount = Math.floor(durationSeconds * sampleRate);
  const buffer = Buffer.alloc(44 + sampleCount * 2);
  buffer.write('RIFF', 0);
  buffer.writeUInt32LE(buffer.length - 8, 4);
  buffer.write('WAVEfmt ', 8);
  buffer.writeUInt32LE(16, 16);
  buffer.writeUInt16LE(1, 20);
  buffer.writeUInt16LE(1, 22);
  buffer.writeUInt32LE(sampleRate, 24);
  buffer.writeUInt32LE(sampleRate * 2, 28);
  buffer.writeUInt16LE(2, 32);
  buffer.writeUInt16LE(16, 34);
  buffer.write('data', 36);
  buffer.writeUInt32LE(sampleCount * 2, 40);
  for (let index = 0; index < sampleCount; index += 1) {
    const envelope = Math.min(1, index / 160) * Math.min(1, (sampleCount - index) / 160);
    buffer.writeInt16LE(Math.round(Math.sin(index * 2 * Math.PI * 440 / sampleRate) * 5000 * envelope), 44 + index * 2);
  }
  return buffer;
}

const AUDIO_FIXTURE = createToneWav(8);
const VIDEO_FIXTURE = Buffer.from('', 'base64');

