function json(value) {
  return JSON.stringify(value);
}

function apiResponse(url, request, requestLog) {
  const account = url.searchParams.get('account') || 'alpha';
  const chat = url.searchParams.get('chat') || '';
  const method = request.method();
  const entry = { method, path: url.pathname, query: Object.fromEntries(url.searchParams.entries()) };
  if (method === 'POST') {
    try { entry.body = request.postDataJSON(); } catch { entry.body = null; }
  }
  requestLog.push(entry);

  if (url.pathname === '/api/accounts') return { accounts, sendingEnabled: true };
  if (url.pathname === '/api/models') return { models: [{ id: 'fixture-model' }], defaultModel: 'fixture-model' };
  if (url.pathname === '/api/chats') return { chats: chats[account] || [] };
  if (url.pathname === '/api/chat-actions' && method === 'POST') return { confirmed: true };
  if (url.pathname === '/api/messages') return { messages: messages[chat] || [] };
  if (url.pathname === '/api/ai/session') return { sessionId: 'fixture-session', messages: [] };
  if (url.pathname === '/api/ai/proposals') return { proposals: [] };
  if (url.pathname === '/api/ai/chat') return { text: 'Respuesta IA fixture para revisar.', sessionId: 'fixture-session' };
  if (url.pathname === '/api/send') return { ok: true, messageId: 'fixture-send' };
  if (url.pathname === '/api/upload') return { ok: true, messageId: 'fixture-upload' };
  return { error: `Unexpected fixture route: ${url.pathname}` };
}

function contentType(filePath) {
  const extension = path.extname(filePath).toLowerCase();
  return {
    '.html': 'text/html; charset=utf-8',
    '.js': 'text/javascript; charset=utf-8',
    '.mjs': 'text/javascript; charset=utf-8',
    '.css': 'text/css; charset=utf-8',
    '.json': 'application/json; charset=utf-8',
    '.svg': 'image/svg+xml',
    '.webmanifest': 'application/manifest+json',
  }[extension] || 'application/octet-stream';
}

async function serveStatic(request, response) {
  const requestUrl = new URL(request.url || '/', 'http://fixture.local');
  if (requestUrl.pathname.startsWith('/media/')) {
    if (requestUrl.pathname === '/media/fixture.wav') {
      response.writeHead(200, { 'content-type': 'audio/wav', 'content-length': AUDIO_FIXTURE.length, 'accept-ranges': 'bytes', 'cache-control': 'no-store' });
      response.end(AUDIO_FIXTURE);
      return;
    }
    if (requestUrl.pathname === '/media/fixture.webm') {
      response.writeHead(200, { 'content-type': 'video/webm', 'content-length': VIDEO_FIXTURE.length, 'accept-ranges': 'bytes', 'cache-control': 'no-store' });
      response.end(VIDEO_FIXTURE);
      return;
    }
    const extension = path.extname(requestUrl.pathname).toLowerCase();
    const mediaType = extension === '.svg' ? 'image/svg+xml' : 'application/pdf';
    const body = extension === '.svg'
      ? '<svg xmlns="http://www.w3.org/2000/svg" width="320" height="180" viewBox="0 0 320 180"><rect width="320" height="180" fill="#21c063"/><circle cx="160" cy="90" r="52" fill="#161717"/><text x="160" y="98" text-anchor="middle" fill="#fafafa" font-family="sans-serif" font-size="28">QA</text></svg>'
      : '';
    response.writeHead(200, { 'content-type': mediaType, 'cache-control': 'no-store' });
    response.end(body);
    return;
  }

  const relative = requestUrl.pathname === '/' ? '/index.html' : requestUrl.pathname;
  const filePath = path.resolve(sourceDir, `.${relative}`);
  if (filePath !== sourceDir && !filePath.startsWith(`${sourceDir}${path.sep}`)) {
    response.writeHead(403);
    response.end('Forbidden');
    return;
  }
  try {
    const body = await fs.readFile(filePath);
    response.writeHead(200, { 'content-type': contentType(filePath), 'cache-control': 'no-store' });
    response.end(body);
  } catch {
    response.writeHead(404);
    response.end('Not found');
  }
}

async function startServer() {
  const server = createServer((request, response) => {
    serveStatic(request, response).catch(error => {
      response.writeHead(500);
      response.end(String(error));
    });
  });
  await new Promise((resolve, reject) => {
    server.once('error', reject);
    server.listen(0, '127.0.0.1', resolve);
  });
  const address = server.address();
  assert(address && typeof address === 'object' && address.port, 'Fixture server did not bind a port');
  return { server, url: `http://127.0.0.1:${address.port}/` };
}

async function waitForApp(page) {
  await page.waitForFunction(() => document.querySelectorAll('#account option').length === 2);
  await page.waitForFunction(() => document.querySelectorAll('#chats .chat-item').length === 2);
}

async function viewportMetrics(page) {
  return page.evaluate(() => ({
    viewportWidth: window.innerWidth,
    viewportHeight: window.innerHeight,
    documentWidth: document.documentElement.scrollWidth,
    bodyWidth: document.body.scrollWidth,
    documentHeight: document.documentElement.scrollHeight,
    bodyHeight: document.body.scrollHeight,
  }));
}

function assertNoOverflow(metrics, label) {
  assert(metrics.documentWidth <= metrics.viewportWidth + 1, `${label}: document overflows horizontally (${JSON.stringify(metrics)})`);
  assert(metrics.bodyWidth <= metrics.viewportWidth + 1, `${label}: body overflows horizontally (${JSON.stringify(metrics)})`);
}

async function assertDesktopGeometry(page) {
  const geometry = await page.evaluate(() => {
    const box = selector => {
      const element = document.querySelector(selector);
      if (!element) return null;
      const rect = element.getBoundingClientRect();
      return { width: rect.width, height: rect.height };
    };
    return {
      rail: box('.app-rail'),
      sidebar: box('.chat-sidebar'),
      sidebarHeader: box('.chat-sidebar-header'),
      chatRow: box('.chat-item'),
      avatar: box('.avatar'),
      conversationHeader: box('.conversation-header'),
      font: getComputedStyle(document.body).fontFamily,
    };
  });
  assert(geometry.rail && Math.abs(geometry.rail.width - 65) <= 2, `desktop rail geometry drifted: ${JSON.stringify(geometry)}`);
  assert(geometry.sidebar && Math.abs(geometry.sidebar.width - 431) <= 2, `desktop sidebar geometry drifted: ${JSON.stringify(geometry)}`);
  assert(geometry.sidebarHeader && Math.abs(geometry.sidebarHeader.height - 64) <= 2, `sidebar header geometry drifted: ${JSON.stringify(geometry)}`);
  assert(geometry.chatRow && Math.abs(geometry.chatRow.height - 76) <= 2, `chat row geometry drifted: ${JSON.stringify(geometry)}`);
  assert(geometry.avatar && Math.abs(geometry.avatar.width - 48) <= 2 && Math.abs(geometry.avatar.height - 48) <= 2, `chat avatar geometry drifted: ${JSON.stringify(geometry)}`);
  assert(geometry.conversationHeader && Math.abs(geometry.conversationHeader.height - 64) <= 2, `conversation header geometry drifted: ${JSON.stringify(geometry)}`);
  assert(geometry.font.includes('Roboto'), `expected Roboto UI font, got ${geometry.font}`);
}

async function selectAccount(page, value) {
  const settings = page.locator('.rail-settings');
  if (!(await settings.evaluate(element => element.open))) {
    await settings.locator('summary').click();
    await page.locator('#account').waitFor({ state: 'visible' });
  }
  await page.locator('#account').selectOption(value);
  await page.waitForFunction(expected => document.querySelector('#account')?.value === expected, value);
  await page.waitForFunction(expected => document.querySelector('#chats')?.textContent.includes(expected), value === 'beta' ? 'Bruno Fixture' : 'Ana Fixture');
}

async function openChat(page, id = 'alpha-chat') {
  const chat = page.locator(`#chats .chat-item`).filter({ hasText: id === 'alpha-chat' ? 'Ana Fixture' : id === 'beta-chat' ? 'Bruno Fixture' : 'Equipo Fixture' }).first();
  await chat.click();
  await page.waitForFunction(expected => document.querySelector('#chat-title')?.textContent.includes(expected), id === 'alpha-chat' ? 'Ana Fixture' : id === 'beta-chat' ? 'Bruno Fixture' : 'Equipo Fixture');
  try {
    await page.waitForFunction(() => {
      const messages = document.querySelector('#messages');
      const text = messages?.textContent || '';
      return Boolean(messages?.querySelector('.message')) || text.includes('[object Object]');
    });
    const messageState = await page.evaluate(() => ({
      hasObjectPlaceholder: document.querySelector('#messages')?.textContent.includes('[object Object]'),
      messageCount: document.querySelectorAll('#messages .message').length,
    }));
    assert.equal(messageState.hasObjectPlaceholder, false, 'message renderer return object was appended as [object Object]');
    assert(messageState.messageCount >= 1, `chat opened without a rendered message bubble: ${JSON.stringify(messageState)}`);
  } catch (error) {
    const state = await page.evaluate(() => ({
      title: document.querySelector('#chat-title')?.textContent,
      messages: document.querySelector('#messages')?.innerHTML.slice(0, 1200),
      visibleError: document.querySelector('#error')?.textContent,
    }));
    await page.screenshot({ path: path.join(outputDir, `debug-open-chat-${id}.png`) });
    throw new Error(`${error.message}; openChat state=${JSON.stringify(state)}`, { cause: error });
  }
}

async function waitForMediaMetadata(locator, label) {
  await locator.evaluate((element, name) => new Promise((resolve, reject) => {
    if (element.readyState >= 1 && Number.isFinite(element.duration) && element.duration > 0) {
      resolve();
      return;
    }
    const timeout = setTimeout(() => reject(new Error(`${name} metadata timeout`)), 5000);
    const finish = () => { clearTimeout(timeout); resolve(); };
    const fail = () => { clearTimeout(timeout); reject(new Error(`${name} media error`)); };
    element.addEventListener('loadedmetadata', finish, { once: true });
    element.addEventListener('error', fail, { once: true });
  }), label);
  const duration = await locator.evaluate(element => Number(element.duration));
  assert(Number.isFinite(duration) && duration > 0, `${label} did not expose a positive duration: ${duration}`);
  return duration;
}

async function assertMediaPlayback(page) {
  const audio = page.locator('.audio-player .audio-element').first();
  const audioDuration = await waitForMediaMetadata(audio, 'audio');
  const audioToggle = page.locator('.audio-toggle').first();
  await audioToggle.click();
  await page.waitForFunction(() => {
    const element = document.querySelector('.audio-player .audio-element');
    return Boolean(element && !element.paused && element.currentTime > 0.05);
  });
  const audioPlayedTime = await audio.evaluate(element => element.currentTime);
  assert(audioPlayedTime > 0.05, `audio currentTime did not advance: ${audioPlayedTime}`);
  await audioToggle.click();
  await page.waitForFunction(() => document.querySelector('.audio-player .audio-element')?.paused === true);
  await page.waitForFunction(() => document.querySelector('.audio-toggle')?.textContent === 'Reproducir');
  assert.equal(await audioToggle.textContent(), 'Reproducir', 'audio pause control did not restore its label');
  await page.locator('.audio-speed').first().selectOption('2');
  assert.equal(await audio.evaluate(element => element.playbackRate), 2, 'audio playback speed did not change');
  await page.waitForFunction(() => {
    const element = document.querySelector('.audio-player .audio-element');
    return Boolean(element?.seekable.length && element.seekable.end(0) > element.seekable.start(0));
  });
  const audioSeekState = await audio.evaluate(element => {
    element.currentTime = 0;
    const progress = element.closest('.audio-player').querySelector('.audio-progress');
    progress.value = '50';
    progress.dispatchEvent(new Event('input', { bubbles: true }));
    return {
      currentTime: element.currentTime,
      duration: element.duration,
      progress: progress.value,
      readyState: element.readyState,
      seekable: element.seekable.length ? [element.seekable.start(0), element.seekable.end(0)] : [],
    };
  });
  const audioSeekTime = audioSeekState.currentTime;
  assert.equal(audioSeekState.progress, '50', `audio seek control value changed unexpectedly: ${JSON.stringify(audioSeekState)}`);
  assert(Math.abs(audioSeekTime - audioDuration / 2) < 0.12, `audio seek did not move to midpoint: ${audioSeekTime}/${audioDuration} state=${JSON.stringify(audioSeekState)}`);

  const video = page.locator('.attachment-video').first();
  const videoDuration = await waitForMediaMetadata(video, 'video');
  await video.evaluate(async element => { await element.play(); });
  await page.waitForFunction(() => (document.querySelector('.attachment-video')?.currentTime || 0) > 0.05);
  const videoPlayedTime = await video.evaluate(element => element.currentTime);
  assert(videoPlayedTime > 0.05, `video currentTime did not advance: ${videoPlayedTime}`);
  await video.evaluate(element => element.pause());
  await page.waitForFunction(() => document.querySelector('.attachment-video')?.paused === true);
  return { audioDuration, audioPlayedTime, audioSeekTime, videoDuration, videoPlayedTime };
}

async function assertPollingPreservesMedia(page) {
  const result = await page.evaluate(async () => {
    const renderer = await import('/message-render.mjs');
    const pane = document.querySelector('#messages');
    const messages = (await (await fetch('/api/messages?account=alpha&chat=alpha-chat')).json()).messages;
    const older = {id:'rolling-old',text:'Earlier fixture',timestamp:'2026-09-22T00:00:00Z',fromMe:true};
    const newer = {id:'rolling-new',text:'New fixture',timestamp:'2026-09-23T08:05:00Z',fromMe:true};
    renderer.reconcileMessageList(pane,[older,...messages]);
    const audio = pane.querySelector('audio'); const video = pane.querySelector('video');
    for (const media of [audio,video]) { media.currentTime=0; media.playbackRate=1; media.loop=false; }
    await Promise.all([audio.play(),video.play()]);
    await new Promise(r=>setTimeout(r,100));
    const before={audio:audio.currentTime,video:video.currentTime};
    renderer.reconcileMessageList(pane,[...messages,newer]);
    await new Promise(r=>setTimeout(r,200));
    const rolling={audioSame:audio===pane.querySelector('audio'),videoSame:video===pane.querySelector('video'),audioPlaying:!audio.paused,videoPlaying:!video.paused,audioAdvanced:audio.currentTime>before.audio,videoAdvanced:video.currentTime>before.video};
    renderer.reconcileMessageList(pane,[older,...messages,newer]);
    const second={audio:audio.currentTime,video:video.currentTime};
    renderer.reconcileMessageList(pane,[{...older,text:'Edited earlier fixture'},...messages,newer]);
    await new Promise(r=>setTimeout(r,200));
    const edit={audioSame:audio===pane.querySelector('audio'),videoSame:video===pane.querySelector('video'),audioPlaying:!audio.paused,videoPlaying:!video.paused,audioAdvanced:audio.currentTime>second.audio,videoAdvanced:video.currentTime>second.video};
    const timing={before,second,after:{audio:audio.currentTime,video:video.currentTime},duration:video.duration}; audio.pause(); video.pause(); return {rolling,edit,timing};
  });
  console.log(JSON.stringify(result)); delete result.timing; for(const [scenario,checks] of Object.entries(result)) for(const [check,value] of Object.entries(checks)) assert.equal(value,true,scenario+': '+check);
  return result;
}

async function assertMediaViewerAccessibility(page) {
  const trigger = page.locator('.media-image-button').first();
  const baselineListeners = await page.evaluate(() => ({ ...window.__qaDocumentKeydowns }));
  await trigger.focus();
  await trigger.click();
  const close = page.getByRole('button', { name: 'Cerrar imagen' });
  await close.waitFor();
  assert.equal(await page.evaluate(() => document.activeElement?.className), 'media-viewer-close', 'image modal did not receive focus');
  await page.keyboard.press('Tab');
  assert.equal(await page.evaluate(() => Boolean(document.querySelector('.media-viewer')?.contains(document.activeElement))), true, 'Tab escaped image modal on first step');
  await page.keyboard.press('Tab');
  assert.equal(await page.evaluate(() => document.activeElement?.className), 'media-viewer-close', 'image modal focus did not wrap');
  await page.keyboard.press('Escape');
  await page.locator('.media-viewer').waitFor({ state: 'detached' });
  assert.equal(await page.evaluate(() => document.activeElement?.classList.contains('media-image-button')), true, 'image modal did not restore focus to its trigger');

  await trigger.click();
  await trigger.click({ force: true });
  await page.getByRole('button', { name: 'Cerrar imagen' }).click();
  await page.locator('.media-viewer').waitFor({ state: 'detached' });
  const finalListeners = await page.evaluate(() => ({ ...window.__qaDocumentKeydowns }));
  assert.equal(finalListeners.added - finalListeners.removed, baselineListeners.added - baselineListeners.removed, `image modal keydown listener leaked: ${JSON.stringify({ baselineListeners, finalListeners })}`);
}

async function assertRecorderConstructorFailure(page) {
  assert.equal(await page.locator('#record').isDisabled(), false, 'record button unavailable for recorder failure scenario');
  await page.locator('#record').click();
  await page.waitForFunction(() => Boolean(document.querySelector('#error')?.textContent));
  await page.waitForFunction(() => (window.__qaRecorder?.tracksStopped || 0) > 0);
  assert.equal(await page.locator('#recording-area').isHidden(), true, 'recording UI remained open after MediaRecorder construction failure');
  return page.evaluate(() => ({ tracksStopped: window.__qaRecorder.tracksStopped, error: document.querySelector('#error')?.textContent }));
}

async function assertPendingSendAccountSwitch(page, controls) {
  controls.holdNextSend();
  await page.locator('#message').fill('pending-confirmed');
  const request = page.waitForRequest(request => request.url().includes('/api/send'));
  const response = page.waitForResponse(response => response.url().includes('/api/send'));
  await page.locator('#composer').evaluate(form => form.requestSubmit());
  await request;
  await selectAccount(page, 'beta');
  controls.releaseSend();
  await response;
  await selectAccount(page, 'alpha');
  await openChat(page, 'alpha-chat');
  assert.equal(await page.locator('#message').inputValue(), '', 'confirmed send left a duplicateable draft after account switch');
}

async function assertMessageSafetyAndMedia(page) {
  await page.waitForFunction(() => document.querySelectorAll('.message').length >= 2);
  assert.equal(await page.locator('.message-sender').count(), 0, 'sender names leaked into a one-to-one chat');
  const messageText = await page.locator('.message-text').first().textContent();
  assert(messageText.includes('<img src=x onerror=window.__fixtureXss=1>'), 'message markup was not preserved as text');
  assert.equal(await page.locator('.message-text img, .message-text script, .message-text iframe, .message-text object').count(), 0, 'message text allowed executable markup');
  assert.equal(await page.evaluate(() => window.__fixtureXss), undefined, 'fixture XSS handler ran');

  const links = await page.locator('a.message-link').evaluateAll(elements => elements.map(element => ({ href: element.href, target: element.target, rel: element.rel })));
  assert(links.some(link => link.href === 'https://example.test/ok'), `safe https link missing: ${JSON.stringify(links)}`);
  assert(links.every(link => ['http:', 'https:', 'mailto:'].includes(new URL(link.href).protocol)), `unsafe link protocol rendered: ${JSON.stringify(links)}`);
  assert(links.every(link => link.target === '_blank' && link.rel.split(/\s+/).includes('noopener')), `external link hardening missing: ${JSON.stringify(links)}`);

  assert.equal(await page.locator('.attachment-image').count(), 1, 'image attachment was not rendered');
  assert.equal(await page.locator('.attachment-video').count(), 1, 'video attachment was not rendered');
  assert.equal(await page.locator('.audio-player .audio-element').count(), 1, 'audio attachment controls were not rendered');
  assert.equal(await page.locator('.attachment-document').count(), 1, 'document attachment card was not rendered');
  assert(await page.locator('.attachment-error').count() >= 1, 'blocked attachment did not render an error state');
  const attachmentLinks = await page.locator('a.attachment-download').evaluateAll(elements => elements.map(element => ({ href: element.href, download: element.download, target: element.target, rel: element.rel })));
  assert(attachmentLinks.length >= 4, `download links missing: ${JSON.stringify(attachmentLinks)}`);
  assert(attachmentLinks.every(link => ['http:', 'https:'].includes(new URL(link.href).protocol)), `unsafe attachment link rendered: ${JSON.stringify(attachmentLinks)}`);

  await page.locator('.media-image-button').click();
  await page.locator('.media-viewer').waitFor();
  assert.equal(await page.locator('.media-viewer-image').getAttribute('alt'), 'fixture.svg');
  await page.getByRole('button', { name: 'Cerrar imagen' }).click();
  await page.locator('.media-viewer').waitFor({ state: 'detached' });
  await assertMediaViewerAccessibility(page);
  return assertMediaPlayback(page);
}

async function assertComposerAndAi(page, requestLog) {
  const sends = () => requestLog.filter(entry => entry.path === '/api/send').length;
  const sendCountBeforeAi = sends();
  await page.locator('#message').fill('draft-alpha');
  assert.equal(await page.locator('#message').inputValue(), 'draft-alpha', 'composer did not preserve typed draft');

  await page.locator('#ai-toggle').click();
  await page.locator('#ai-panel').waitFor({ state: 'visible' });
  await page.locator('#ai-prompt').waitFor();
  assert.equal((await page.locator('#ai-panel-title').textContent()).trim(), 'Social Media Agent', 'the agent panel is not titled Social Media Agent');
  assert.equal(await page.locator('#ai-panel input, #ai-panel select').count(), 0, 'the agent panel exposes configuration controls');
  assert.equal((await page.locator('#ai-panel').innerText()).includes('Asistente privado'), false, 'the agent panel keeps the private assistant label');
  await page.locator('#ai-prompt').fill('Resume este fixture');
  await page.locator('#ai-send').click();
  await page.locator('.ai-bubble-in').getByText('Respuesta IA fixture').waitFor();
  const aiRequest = requestLog.findLast(entry => entry.path === '/api/ai/chat');
  assert.deepEqual(aiRequest?.body, { account: 'alpha', chat: 'alpha-chat', message: 'Resume este fixture', allowPropose: true, allowSend: true });
  assert.equal(await page.locator('#ai-use-draft').isEnabled(), true, 'AI draft action stayed disabled');
  await page.locator('#ai-use-draft').click();
  assert.equal(await page.locator('#message').inputValue(), 'draft-alpha\n\nRespuesta IA fixture para revisar.', 'the draft action did not extend the typed draft');
  assert.equal(sends(), sendCountBeforeAi, 'AI draft unexpectedly sent a WhatsApp message');

  await page.locator('#message').fill('mocked composer send');
  await page.locator('#composer').evaluate(form => form.requestSubmit());
  await page.waitForFunction(() => document.querySelector('#message')?.value === '');
  const sendEntries = requestLog.filter(entry => entry.path === '/api/send');
  assert.equal(sendEntries.length, sendCountBeforeAi + 1, 'composer did not use the mocked send endpoint');
  assert.equal(sendEntries.at(-1)?.body?.text, 'mocked composer send', 'composer payload changed unexpectedly');

  const sendsBeforeDraft = sends();
  await page.locator('#suggest').click();
  await page.waitForFunction(() => document.querySelector('#message')?.value === 'Respuesta IA fixture para revisar.');
  assert.equal(sends(), sendsBeforeDraft, 'Proponer mensaje sent a WhatsApp message');
  const draftRequest = requestLog.findLast(entry => entry.path === '/api/ai/chat');
  assert.equal(draftRequest?.body?.allowPropose, true, 'Proponer mensaje did not request a scoped proposal grant');
  assert.equal(draftRequest?.body?.allowSend, false, 'Proponer mensaje requested direct sending');
  assert.match(draftRequest?.body?.message || '', /Propón un mensaje/, 'Proponer mensaje did not ask the agent session');

  await page.locator('#message').fill('draft-alpha-restored');
  if (await page.locator('#ai-panel').isVisible()) await page.locator('#ai-close').click();
  await page.locator('#ai-panel').waitFor({ state: 'hidden' });
}

async function runDesktop(browser, baseUrl) {
  const context = await browser.newContext({ viewport: { width: 1440, height: 675 }, reducedMotion: 'reduce' });
  await context.addInitScript(() => {
    window.__qaRecorder = { tracksStopped: 0 };
    const fixtureTrack = { stop: () => { window.__qaRecorder.tracksStopped += 1; } };
    const fixtureStream = { getTracks: () => [fixtureTrack] };
    const getUserMedia = async () => fixtureStream;
    try {
      Object.defineProperty(navigator, 'mediaDevices', { configurable: true, value: { getUserMedia } });
    } catch {
      navigator.mediaDevices.getUserMedia = getUserMedia;
    }
    window.MediaRecorder = class FixtureMediaRecorder {
      static isTypeSupported() { return true; }
      constructor() { throw new Error('fixture MediaRecorder failure'); }
    };

    window.__qaPolling = null;
    const nativeSetInterval = window.setInterval.bind(window);
    window.setInterval = (callback, delay, ...args) => {
      if (delay === 10000) window.__qaPolling = callback;
      return nativeSetInterval(callback, delay, ...args);
    };

    window.__qaDocumentKeydowns = { added: 0, removed: 0 };
    const nativeAdd = Document.prototype.addEventListener;
    const nativeRemove = Document.prototype.removeEventListener;
    Document.prototype.addEventListener = function (type, listener, options) {
      if (type === 'keydown') window.__qaDocumentKeydowns.added += 1;
      return nativeAdd.call(this, type, listener, options);
    };
    Document.prototype.removeEventListener = function (type, listener, options) {
      if (type === 'keydown') window.__qaDocumentKeydowns.removed += 1;
      return nativeRemove.call(this, type, listener, options);
    };
  });
  const page = await context.newPage();
  const requestLog = [];
  const dialogs = [];
  const pageErrors = [];
  const consoleErrors = [];
  let holdNextSend = false;
  let releaseSendGate = null;
  let sendGate = Promise.resolve();
  const sendControls = {
    holdNextSend() {
      holdNextSend = true;
      sendGate = new Promise(resolve => { releaseSendGate = resolve; });
    },
    releaseSend() {
      releaseSendGate?.();
      releaseSendGate = null;
    },
  };
  page.on('dialog', dialog => { dialogs.push(dialog.type()); void dialog.dismiss(); });
  page.on('pageerror', error => pageErrors.push(error.message));
  page.on('console', message => { if (message.type() === 'error') consoleErrors.push(message.text()); });
  await page.route('**/api/**', async route => {
    const url = new URL(route.request().url());
    if (url.pathname === '/api/ai/sessions') await new Promise(resolve => setTimeout(resolve, 40));
    if (url.pathname === '/api/send' && holdNextSend) {
      holdNextSend = false;
      await sendGate;
    }
    await route.fulfill({ status: 200, contentType: 'application/json', body: json(apiResponse(url, route.request(), requestLog)) });
  });
  await page.goto(baseUrl);
  await waitForApp(page);
  await assertDesktopGeometry(page);
  assertNoOverflow(await viewportMetrics(page), 'desktop initial');
  await page.screenshot({ path: path.join(outputDir, 'desktop-initial-1440x675.png') });

  await openChat(page);
  const mediaPlayback = await assertMessageSafetyAndMedia(page);
  const pollingMedia = await assertPollingPreservesMedia(page);
  const recorderFailure = await assertRecorderConstructorFailure(page);
  await assertPendingSendAccountSwitch(page, sendControls);
  await assertComposerAndAi(page, requestLog);
  assertNoOverflow(await viewportMetrics(page), 'desktop chat');
  await page.screenshot({ path: path.join(outputDir, 'desktop-chat-1440x675.png') });

  assert.equal(await page.locator('#back').isVisible(), false, 'desktop unexpectedly exposes the mobile back button');
  await selectAccount(page, 'beta');
  assert.equal(await page.locator('body').evaluate(element => element.classList.contains('chat-open')), false, 'account switch did not return to the desktop chat list');
  assert.equal(await page.locator('#message').inputValue(), '', 'account switch leaked the previous draft');
  await openChat(page, 'beta-chat');
  await page.locator('#message').fill('draft-beta');
  await selectAccount(page, 'alpha');
  await openChat(page, 'alpha-chat');
  assert.equal(await page.locator('#message').inputValue(), 'draft-alpha-restored', 'chat draft was not restored after account switch');
  await openChat(page, 'alpha-other');
  assert.equal(await page.locator('.message-sender').count(), 1, 'group chat omitted the sender name');
  assert.equal(await page.locator('.message-sender').first().textContent(), 'Equipo Fixture');
  assertNoOverflow(await viewportMetrics(page), 'desktop after account switch');
  assert.deepEqual(dialogs, [], `unexpected browser dialogs: ${JSON.stringify(dialogs)}`);
  assert.deepEqual(pageErrors, [], `page errors: ${JSON.stringify(pageErrors)}`);
  assert.deepEqual(consoleErrors, [], `console errors: ${JSON.stringify(consoleErrors)}`);
  await page.screenshot({ path: path.join(outputDir, 'desktop-account-switch-1440x675.png') });
  await context.close();
  return { viewport: '1440x675', touch: false, requestLog, dialogs, pageErrors, consoleErrors, mediaPlayback, pollingMedia, recorderFailure };
}

async function runMobile(browser, baseUrl) {
  const context = await browser.newContext({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true, reducedMotion: 'reduce' });
  const page = await context.newPage();
  const requestLog = [];
  const dialogs = [];
  const pageErrors = [];
  const consoleErrors = [];
  page.on('dialog', dialog => { dialogs.push(dialog.type()); void dialog.dismiss(); });
  page.on('pageerror', error => pageErrors.push(error.message));
  page.on('console', message => { if (message.type() === 'error') consoleErrors.push(message.text()); });
  await page.route('**/api/**', async route => {
    const url = new URL(route.request().url());
    await route.fulfill({ status: 200, contentType: 'application/json', body: json(apiResponse(url, route.request(), requestLog)) });
  });
  await page.goto(baseUrl);
  await waitForApp(page);
  assert.equal(await page.evaluate(() => navigator.maxTouchPoints > 0), true, 'mobile context did not expose touch input');
  assertNoOverflow(await viewportMetrics(page), 'mobile initial');
  await page.screenshot({ path: path.join(outputDir, 'mobile-list-390x844.png') });

  await openChat(page);
  assert.equal(await page.locator('.chat-sidebar').evaluate(element => getComputedStyle(element).display), 'none', 'mobile chat list stayed visible after opening');
  assert.notEqual(await page.locator('.conversation').evaluate(element => getComputedStyle(element).display), 'none', 'mobile conversation stayed hidden after opening');
  const mobileChatGeometry = await page.evaluate(() => ({
    railDisplay: getComputedStyle(document.querySelector('.app-rail')).display,
    conversationWidth: document.querySelector('.conversation')?.getBoundingClientRect().width,
    viewportWidth: window.innerWidth,
  }));
  assert.equal(mobileChatGeometry.railDisplay, 'none', `mobile rail stayed visible in chat: ${JSON.stringify(mobileChatGeometry)}`);
  assert(Math.abs(mobileChatGeometry.conversationWidth - mobileChatGeometry.viewportWidth) <= 1, `mobile chat did not expand to full width: ${JSON.stringify(mobileChatGeometry)}`);
  assertNoOverflow(await viewportMetrics(page), 'mobile chat');
  await page.screenshot({ path: path.join(outputDir, 'mobile-chat-390x844.png') });

  await page.locator('#back').click();
  assert.equal(await page.locator('body').evaluate(element => element.classList.contains('chat-open')), false, 'mobile back did not return to chat list');
  assert.notEqual(await page.locator('.chat-sidebar').evaluate(element => getComputedStyle(element).display), 'none', 'mobile chat list remained hidden after back');
  assertNoOverflow(await viewportMetrics(page), 'mobile back');
  await selectAccount(page, 'beta');
  assertNoOverflow(await viewportMetrics(page), 'mobile account popover');
  assert.deepEqual(dialogs, [], `unexpected mobile browser dialogs: ${JSON.stringify(dialogs)}`);
  assert.deepEqual(pageErrors, [], `mobile page errors: ${JSON.stringify(pageErrors)}`);
  assert.deepEqual(consoleErrors, [], `mobile console errors: ${JSON.stringify(consoleErrors)}`);
  await context.close();
  return { viewport: '390x844', touch: true, requestLog, dialogs, pageErrors, consoleErrors };
}

async function main() {
  await fs.mkdir(outputDir, { recursive: true });
  const { server, url } = await startServer();
  const browser = await chromium.launch({ headless: true, executablePath });
  try {
    const desktop = await runDesktop(browser, url);
    const mobile = await runMobile(browser, url);
    const summary = {
      sourceDir,
      fixtureUrl: url,
      browser: { executablePath, chromium: true },
      checks: {
        desktop: 'passed',
        mobileTouch: 'passed',
        horizontalOverflow: 'passed',
        accountSwitchAndDraftIsolation: 'passed',
        chatListDetailBack: 'passed',
        safeLinksAndNoScriptInjection: 'passed',
        imageVideoAudioDocumentRendering: 'passed',
        realAudioPlayback: 'passed',
        realVideoPlayback: 'passed',
        composerAndAiMockedRequests: 'passed',
        recorderFailureStopsTracks: 'passed',
        pollingPreservesMedia: 'passed',
        aiSessionRaceIsolation: 'passed',
        mediaViewerFocusAndListenerCleanup: 'passed',
        confirmedSendDraftCleanup: 'passed',
      },
      runs: [desktop, mobile],
      screenshots: await fs.readdir(outputDir),
    };
    await fs.writeFile(path.join(outputDir, 'ui-visual-summary.json'), `${JSON.stringify(summary, null, 2)}\n`);
    process.stdout.write(`${JSON.stringify(summary, null, 2)}\n`);
  } finally {
    await browser.close();
    await new Promise(resolve => server.close(resolve));
  }
}

main().catch(error => {
  process.stderr.write(`${error.stack || error}\n`);
  process.exitCode = 1;
});
